<parameter name="content">import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("[ErrorBoundary]", error.message, {
      stack: error.stack,
      componentStack: errorInfo.componentStack,
    });
    this.props.onError?.(error, errorInfo);
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.retry);

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.title}>Something went wrong</h2>
        <pre style={styles.message}>{error.message}</pre>
        <button onClick={this.retry} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

const styles = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
    backgroundColor: "#fef2f2",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title: { margin: "0 0 0.5rem", color: "#b91c1c", fontSize: "1.25rem" },
  message: {
    margin: "0 0 1rem",
    color: "#7f1d1d",
