  },
  button: {
    padding: "0.5rem 1rem",
    backgroundColor: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "0.25rem",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
} as const;
